import { useMemo } from 'react'
import type { ComponentProps, ReactNode } from 'react'
import { useTranslation } from 'react-i18next'
import { getRouteApi } from '@tanstack/react-router'
import { useGetDashboard } from '@bk-dash/client-typescript/typescript'
import type { GetDashboard200 } from '@bk-dash/client-typescript/typescript'

import { Card } from '@/components/ui/card'
import { Skeleton } from '@/components/ui/skeleton'
import { GradientIconBadge } from '@/components/ui/gradient-icon-badge'
import { BalanceIcon, CardIcon, CashIcon, LockIcon, OrderBlockIcon, ReturnIcon, ToolIcon } from '@/components/ui/icons'
import type { IconComponent } from '@/components/ui/icons'
import { formatMoneyValue, sumMoney, type MoneyValue } from '@/lib/format'
import { cn } from '@/lib/utils'
import { useTenancyStore } from '@/stores'

import { DiscountCostsToggle } from './DiscountCostsToggle'
import { AdditionalCostRow } from './AdditionalCostRow'
import { CostTooltipLines, OperationalTooltip, type CostTooltipLine } from './CostTooltips'

const routeApi = getRouteApi('/(app)/dashboard/')

type AdditionalCost = GetDashboard200['additionalCost']

// Rows summed into the header total + rendered in order. Typed off the additionalCost schema so the
// row set AND the loading skeleton stay in sync. (draftOrders is national-only + informational, so
// it's appended separately and excluded from the total.)
const COST_KEYS = ['chargeback', 'refund', 'taxes', 'operational', 'warranty'] as const satisfies readonly (keyof AdditionalCost)[]

const DEFAULT_CURRENCY = 'BRL'

interface CostRowView {
	key: string
	icon: IconComponent
	label: string
	value: string
	tooltip: ReactNode
}

/**
 * Additional Costs card — the period's cost categories read from `GetDashboard`'s `additionalCost`
 * top-level, each row revealing its sub-breakdown on hover (operational uses a custom titled
 * tooltip). Owns the dashboard query, feeds rows by props. Works in mono (single-store) and
 * consolidated (multi-store) tenancy via `MoneyValue`. `draftOrders` shows only in *_NATIONAL.
 * All copy is i18n-driven; currency formatting follows the active locale.
 */
export function AdditionalCostsSection({ className, ...props }: ComponentProps<'div'>) {
	const { t, i18n } = useTranslation()
	const locale = i18n.language?.startsWith('en') ? 'en-US' : 'pt-BR'
	const { startDate, endDate, productIds } = routeApi.useSearch()
	const tenancyScope = useTenancyStore(s => s.tenancyScope)
	const { data, isPending, isError } = useGetDashboard({ tenancyScope, startDate, endDate, productIds })

	const view = useMemo(() => {
		if (!data) return null

		const currency = data.kind === 'SINGLE_GLOBAL' || data.kind === 'SINGLE_NATIONAL' ? data.store.currency : DEFAULT_CURRENCY
		const money = (value: MoneyValue) => formatMoneyValue(value, currency, locale)
		const lines = (items: CostTooltipLine[]): ReactNode => <CostTooltipLines lines={items} />
		const ac = data.additionalCost

		const byKey: Record<(typeof COST_KEYS)[number], { icon: IconComponent; label: string; total: MoneyValue; tooltip: ReactNode }> = {
			chargeback: {
				icon: CardIcon,
				label: t('dashboard.additionalCosts.rows.chargeback'),
				total: ac.chargeback.byStatus.total.value,
				tooltip: lines([
					{ label: t('dashboard.additionalCosts.tooltip.open'), value: money(ac.chargeback.byStatus.segments.OPEN.value) },
					{ label: t('dashboard.additionalCosts.tooltip.lost'), value: money(ac.chargeback.byStatus.segments.LOST.value) },
					{ label: t('dashboard.additionalCosts.tooltip.won'), value: money(ac.chargeback.byStatus.segments.WON.value) },
					{ label: t('dashboard.additionalCosts.tooltip.fees'), value: money(ac.chargeback.fees.value) },
				]),
			},
			refund: {
				icon: ReturnIcon,
				label: t('dashboard.additionalCosts.rows.refund'),
				total: ac.refund.value,
				tooltip: lines([{ label: t('dashboard.additionalCosts.tooltip.total'), value: money(ac.refund.value) }]),
			},
			taxes: {
				icon: BalanceIcon,
				label: t('dashboard.additionalCosts.rows.taxes'),
				total: sumMoney([ac.taxes.ads.value, ac.taxes.others.value]),
				tooltip: lines([
					{ label: t('dashboard.additionalCosts.tooltip.ads'), value: money(ac.taxes.ads.value) },
					{ label: t('dashboard.additionalCosts.tooltip.others'), value: money(ac.taxes.others.value) },
				]),
			},
			operational: {
				icon: ToolIcon,
				label: t('dashboard.additionalCosts.rows.operational'),
				total: ac.operational.total.value,
				tooltip: <OperationalTooltip operational={ac.operational} />,
			},
			warranty: {
				icon: LockIcon,
				label: t('dashboard.additionalCosts.rows.warranty'),
				total: ac.warranty.value,
				tooltip: lines([{ label: t('dashboard.additionalCosts.tooltip.total'), value: money(ac.warranty.value) }]),
			},
		}

		const rows: CostRowView[] = COST_KEYS.map(key => {
			const r = byKey[key]
			return { key, icon: r.icon, label: r.label, value: money(r.total), tooltip: r.tooltip }
		})

		// draftOrders — national only (the discriminated union carries it on the *_NATIONAL variants);
		// informational (count + value of draft orders), not summed into the total.
		if (data.kind === 'SINGLE_NATIONAL' || data.kind === 'MULTI_NATIONAL') {
			const draftOrders = data.additionalCost.draftOrders
			rows.push({
				key: 'draftOrders',
				icon: OrderBlockIcon,
				label: t('dashboard.additionalCosts.rows.draftOrders'),
				value: money(draftOrders.value.value),
				tooltip: lines([{ label: t('dashboard.additionalCosts.tooltip.count'), value: String(draftOrders.count.value) }]),
			})
		}

		const headerTotal = money(sumMoney(COST_KEYS.map(key => byKey[key].total)))
		return { headerTotal, rows }
	}, [data, t, locale])

	return (
		<Card className={cn('gap-4 p-6', className)} {...props}>
			<div className="flex items-center gap-4">
				<GradientIconBadge icon={CashIcon} />
				<div className="flex min-w-0 flex-col gap-2">
					<span className="text-muted-foreground text-lg font-medium">{t('dashboard.additionalCosts.title')}</span>
					{isPending ? (
						<Skeleton className="mt-1 h-8 w-32" />
					) : (
						<span className="truncate text-3xl font-bold text-foreground">{view ? view.headerTotal : '—'}</span>
					)}
				</div>
			</div>

			<DiscountCostsToggle className="mx-2" />

			<div className="border-t border-border/60" />

			<div className="flex flex-col gap-3" role="list" aria-label={t('dashboard.additionalCosts.listAria')}>
				{isPending ? (
					COST_KEYS.map(key => <Skeleton key={key} className="h-5 w-full" />)
				) : isError || !view ? (
					<p className="text-sm text-muted-foreground">{t('dashboard.additionalCosts.loadError')}</p>
				) : (
					view.rows.map(row => (
						<AdditionalCostRow key={row.key} icon={row.icon} label={row.label} value={row.value} tooltip={row.tooltip} />
					))
				)}
			</div>
		</Card>
	)
}

import type { ComponentProps, ReactNode } from 'react'

import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip'
import { GradientIcon } from '@/components/ui/gradient-icon'
import type { IconComponent } from '@/components/ui/icons'
import { cn } from '@/lib/utils'

interface AdditionalCostRowProps extends ComponentProps<'div'> {
	icon: IconComponent
	label: string
	/** Pre-formatted display string for the row's total. */
	value: string
	/** Custom hover content; when present the label becomes the trigger. */
	tooltip?: ReactNode
}

/**
 * One line of the Additional Costs card. Presentational leaf — the owning Section formats the value
 * and builds the tooltip node. When `tooltip` is provided the label reveals it on hover.
 */
export function AdditionalCostRow({ icon: Icon, label, value, tooltip, className, ...props }: AdditionalCostRowProps) {
	return (
		<div role="listitem" className={cn('flex items-center gap-3', className)} {...props}>
			<GradientIcon icon={Icon} className="size-4 shrink-0 text-muted-foreground" />
			{tooltip ? (
				<Tooltip>
					<TooltipTrigger className="border-dashed border-muted-foreground/40 text-sm text-foreground">{label}</TooltipTrigger>
					<TooltipContent>{tooltip}</TooltipContent>
				</Tooltip>
			) : (
				<span className="text-sm text-foreground">{label}</span>
			)}
			<span className="ml-auto text-sm font-medium text-destructive">{value}</span>
		</div>
	)
}

import { useTranslation } from 'react-i18next'
import type { GetDashboard200 } from '@bk-dash/client-typescript/typescript'

import { enumLabel } from '@/lib/enums'
import { formatCurrency } from '@/lib/format'

export interface CostTooltipLine {
	label: string
	value: string
}

/** Standard breakdown tooltip: left-aligned `label: value` lines. */
export function CostTooltipLines({ lines }: { lines: CostTooltipLine[] }) {
	return (
		<div className="flex flex-col gap-1">
			{lines.map(line => (
				<div key={line.label} className="flex justify-between gap-2">
					<span className="text-muted-foreground">{line.label}:</span>
					<span className="font-medium text-foreground">{line.value}</span>
				</div>
			))}
		</div>
	)
}

type OperationalDetail = GetDashboard200['additionalCost']['operational']

/**
 * Operational tooltip — a titled list of each operational cost (`name (freq)` / amount). Takes the
 * `additionalCost.operational` detail entry directly and owns its own i18n + currency formatting.
 */
export function OperationalTooltip({ operational }: { operational: OperationalDetail }) {
	const { t, i18n } = useTranslation()
	const locale = i18n.language?.startsWith('en') ? 'en-US' : 'pt-BR'

	return (
		<div className="flex min-w-44 flex-col gap-1.5">
			<div className="text-center font-semibold text-foreground">{t('dashboard.additionalCosts.tooltip.operationalTitle')}</div>
			{operational.items.length ? (
				operational.items.map(item => (
					<div key={item.id} className="flex items-center justify-between gap-6">
						<span className="text-muted-foreground">
							{item.name} ({enumLabel('OperationalCostRecurrency', item.frequency)})
						</span>
						<span className="font-medium text-foreground">{formatCurrency(item.amount, item.currency, locale)}</span>
					</div>
				))
			) : (
				<div className="text-center text-muted-foreground">{t('dashboard.additionalCosts.tooltip.noCosts')}</div>
			)}
		</div>
	)
}

import type { ComponentProps } from 'react'
import { useTranslation } from 'react-i18next'

import { Checkbox } from '@/components/ui/checkbox'
import { Label } from '@/components/ui/label'
import { cn } from '@/lib/utils'
import { useDashboardStore } from '../../-stores/useDashboardStore'

/**
 * Store-backed checkbox. Writing `discountAdditionalCosts` lets the other dashboard cards decide
 * whether to subtract additional costs from profit/margin. Not a URL param — it is a cross-card
 * display preference (see useDashboardStore).
 */
export function DiscountCostsToggle({ className, ...props }: ComponentProps<typeof Label>) {
	const { t } = useTranslation()
	const discountAdditionalCosts = useDashboardStore(s => s.discountAdditionalCosts)
	const setDiscountAdditionalCosts = useDashboardStore(s => s.setDiscountAdditionalCosts)
	const label = t('dashboard.additionalCosts.discountToggle')

	return (
		<Label className={cn('cursor-pointer gap-3 text-muted-foreground', className)} {...props}>
			<Checkbox
				checked={discountAdditionalCosts}
				onCheckedChange={checked => setDiscountAdditionalCosts(checked === true)}
				aria-label={label}
			/>
			{label}
		</Label>
	)
}

/**
 * Currency formatting for display strings. Components pre-format numbers before passing them to
 * presentational primitives (StatCard, AdditionalCostRow) — the value prop is always a finished
 * string, never a raw number.
 */
export function formatCurrency(value: number, currency: string, locale = 'pt-BR'): string {
	return new Intl.NumberFormat(locale, {
		style: 'currency',
		currency,
		minimumFractionDigits: 2,
	}).format(value)
}

/**
 * A money metric value as it arrives from GetDashboard: a plain `number` in single-store
 * (mono-currency) mode, or a sparse `{ [CurrencyCode]: number }` record in consolidated
 * (multi-store) mode. Letting both flow through one type lets the cost card render identically in
 * either tenancy scope.
 */
export type MoneyValue = number | Record<string, number>

/** Format a MoneyValue. Records render each currency formatted in its own code, joined by " · ". */
export function formatMoneyValue(value: MoneyValue, fallbackCurrency: string, locale = 'pt-BR'): string {
	if (typeof value === 'number') return formatCurrency(value, fallbackCurrency, locale)
	const entries = Object.entries(value)
	if (entries.length === 0) return formatCurrency(0, fallbackCurrency, locale)
	return entries.map(([code, amount]) => formatCurrency(amount, code, locale)).join(' · ')
}

/** Sum MoneyValues: numeric values add; record values merge per currency code. */
export function sumMoney(values: MoneyValue[]): MoneyValue {
	if (values.every(value => typeof value === 'number')) {
		return (values as number[]).reduce((acc, value) => acc + value, 0)
	}
	const acc: Record<string, number> = {}
	for (const value of values) {
		if (typeof value === 'number') continue
		for (const [code, amount] of Object.entries(value)) acc[code] = (acc[code] ?? 0) + amount
	}
	return acc
}

import { create } from 'zustand'
import { persist } from 'zustand/middleware'

/**
 * Dashboard-scoped display preferences shared across cards (e.g. the Additional Costs card
 * toggles `discountAdditionalCosts`, which the profit/margin cards read to decide whether to
 * subtract those costs). Persisted so the choice survives refresh.
 */
interface DashboardStore {
	discountAdditionalCosts: boolean
	setDiscountAdditionalCosts: (value: boolean) => void
	toggleDiscountAdditionalCosts: () => void
}

export const useDashboardStore = create<DashboardStore>()(
	persist(
		set => ({
			discountAdditionalCosts: false,
			setDiscountAdditionalCosts: value => set({ discountAdditionalCosts: value }),
			toggleDiscountAdditionalCosts: () => set(s => ({ discountAdditionalCosts: !s.discountAdditionalCosts })),
		}),
		{ name: 'dashboard-storage' },
	),
)

import { useState } from 'react'
import type { Meta, StoryObj } from '@storybook/react'
import { QueryClient, QueryClientProvider } from '@tanstack/react-query'
import { RouterProvider, createMemoryHistory, createRootRoute, createRoute, createRouter } from '@tanstack/react-router'
import { http, HttpResponse, delay } from 'msw'
import type { GetDashboardQueryResponse, TenancyScope } from '@bk-dash/client-typescript/typescript'

import { useTenancyStore } from '@/stores'
import { dashboardSearchSchema } from '../../index'
import { AdditionalCostsSection } from '.'

// ---------------------------------------------------------------------------
// Mock GetDashboard responses. Only the `additionalCost` paths the card reads are populated; the
// rest of the payload (stat, etc.) is omitted and cast. Single-store uses numeric metric values;
// consolidated (multi-store) uses per-currency records to exercise the " · " multi-currency format.
// ---------------------------------------------------------------------------
const m = (value: number) => ({ value, deltaPct: null })
const mr = (brl: number, usd: number) => ({ value: { BRL: brl, USD: usd }, deltaPct: null })

const operationalItems = [
	{
		id: '1',
		name: '123',
		flow: 'EXPENSE',
		frequency: 'ONCE',
		amount: 10,
		currency: 'BRL',
		startDate: '2026-06-01T00:00:00Z',
		endDate: null,
	},
	{
		id: '2',
		name: 'Servidor',
		flow: 'EXPENSE',
		frequency: 'MONTHLY',
		amount: 120,
		currency: 'BRL',
		startDate: '2026-06-01T00:00:00Z',
		endDate: null,
	},
]

function singleAdditionalCost(v: number, items: typeof operationalItems = []) {
	return {
		chargeback: {
			byStatus: { total: m(v * 3), segments: { OPEN: m(v), UNDER_REVIEW: m(0), WON: m(v), LOST: m(v), ACCEPTED: m(0) } },
			fees: m(v),
		},
		refund: m(v),
		taxes: { ads: m(v), others: m(v) },
		operational: { total: m(v * 2), items },
		warranty: m(v),
	}
}

function singleResponse(v: number, items: typeof operationalItems = []): GetDashboardQueryResponse {
	return {
		kind: 'SINGLE_GLOBAL',
		tenancyScope: 'SINGLE_STORE',
		dashboardMode: 'GLOBAL',
		store: { id: 'store-1', currency: 'BRL' },
		additionalCost: singleAdditionalCost(v, items),
	} as unknown as GetDashboardQueryResponse
}

function nationalResponse(v: number, items: typeof operationalItems = []): GetDashboardQueryResponse {
	return {
		kind: 'SINGLE_NATIONAL',
		tenancyScope: 'SINGLE_STORE',
		dashboardMode: 'NATIONAL',
		store: { id: 'store-1', currency: 'BRL' },
		additionalCost: { ...singleAdditionalCost(v, items), draftOrders: { count: m(7), value: m(350) } },
	} as unknown as GetDashboardQueryResponse
}

function multiResponse(): GetDashboardQueryResponse {
	const a = mr(100, 20)
	return {
		kind: 'MULTI_GLOBAL',
		tenancyScope: 'MULTI_STORE',
		dashboardMode: 'GLOBAL',
		additionalCost: {
			chargeback: {
				byStatus: { total: mr(300, 60), segments: { OPEN: a, UNDER_REVIEW: a, WON: a, LOST: a, ACCEPTED: a } },
				fees: a,
			},
			refund: a,
			taxes: { ads: a, others: a },
			operational: { total: mr(200, 40), items: [] },
			warranty: a,
		},
	} as unknown as GetDashboardQueryResponse
}

const DASHBOARD_ENDPOINT = '*/v1/ui/dashboard'
const respondWith = (res: GetDashboardQueryResponse) => http.get(DASHBOARD_ENDPOINT, () => HttpResponse.json(res))

// ---------------------------------------------------------------------------
// Stub router — mounts the data-fetching Section at the dashboard route id so its
// `getRouteApi('/(app)/dashboard/').useSearch()` resolves (search defaults come from the route's
// own schema). MSW answers the GetDashboard request; the QueryClient powers `useGetDashboard`.
// ---------------------------------------------------------------------------
function buildRouter() {
	const rootRoute = createRootRoute()
	const appLayout = createRoute({ getParentRoute: () => rootRoute, id: '(app)' })
	const dashboardRoute = createRoute({
		getParentRoute: () => appLayout,
		path: 'dashboard/',
		validateSearch: search => dashboardSearchSchema.parse(search ?? {}),
		component: AdditionalCostsSection,
	})
	const routeTree = rootRoute.addChildren([appLayout.addChildren([dashboardRoute])])
	return createRouter({ routeTree, history: createMemoryHistory({ initialEntries: ['/dashboard'] }) })
}

function StoryCard({ scope = 'SINGLE_STORE' as TenancyScope }: { scope?: TenancyScope }) {
	// Set the app-global tenancy scope this story exercises before the Section reads it.
	useTenancyStore.setState({ tenancyScope: scope })
	const [queryClient] = useState(() => new QueryClient({ defaultOptions: { queries: { retry: false } } }))
	const [router] = useState(buildRouter)
	return (
		<div className="w-[420px]">
			<QueryClientProvider client={queryClient}>
				<RouterProvider router={router} />
			</QueryClientProvider>
		</div>
	)
}

const meta: Meta<typeof StoryCard> = {
	title: 'Dashboard/AdditionalCostsCard',
	component: StoryCard,
	parameters: { layout: 'centered' },
}
export default meta
type Story = StoryObj<typeof StoryCard>

/** Populated single-store costs — hover a row for its breakdown; operational has a titled tooltip. */
export const Default: Story = {
	parameters: { msw: { handlers: [respondWith(singleResponse(150.5, operationalItems))] } },
	render: () => <StoryCard />,
}

/** All-zero period — mirrors the reference mockup ("R$ 0,00"). */
export const Zeroed: Story = {
	parameters: { msw: { handlers: [respondWith(singleResponse(0))] } },
	render: () => <StoryCard />,
}

/** National mode — adds the `draftOrders` row; operational tooltip shows `name (1x)` + amount. */
export const National: Story = {
	parameters: { msw: { handlers: [respondWith(nationalResponse(150.5, operationalItems))] } },
	render: () => <StoryCard />,
}

/** Consolidated (multi-store) — same rows, values formatted per currency (e.g. "R$ … · US$ …"). */
export const Consolidated: Story = {
	parameters: { msw: { handlers: [respondWith(multiResponse())] } },
	render: () => <StoryCard scope="MULTI_STORE" />,
}

/** Pending query — header value + rows show skeletons. */
export const Loading: Story = {
	parameters: {
		msw: {
			handlers: [
				http.get(DASHBOARD_ENDPOINT, async () => {
					await delay('infinite')
					return HttpResponse.json(singleResponse(0))
				}),
			],
		},
	},
	render: () => <StoryCard />,
}

/** Request fails (400 → no ky retry) — inline error message. */
export const ErrorState: Story = {
	parameters: { msw: { handlers: [http.get(DASHBOARD_ENDPOINT, () => new HttpResponse(null, { status: 400 }))] } },
	render: () => <StoryCard />,
}
